import polars as pl

def transform(raw: pl.DataFrame) -> pl.DataFrame:
    missing_placeholders = {"", "N/A", "n/a", "-", "null", "NULL"}

    def clean_str(col: str) -> pl.Expr:
        s = pl.col(col).str.strip_chars()
        return pl.when(s.is_in(list(missing_placeholders))).then(None).otherwise(s)

    return raw.select(
        order_id=clean_str("order_no").str.to_uppercase(),
        line_no=clean_str("items.line").cast(pl.Int64, strict=False),
        sold_at=clean_str("created").str.to_datetime("%Y-%m-%dT%H:%M:%S", strict=False),
        store=clean_str("@export.store").str.to_uppercase(),
        sku=clean_str("items.sku").str.to_uppercase(),
        qty=clean_str("items.qty").cast(pl.Int64, strict=False),
        unit_price=clean_str("items.price").cast(pl.Float64, strict=False).round(2),
        discount=clean_str("items.discount").cast(pl.Float64, strict=False).round(2),
        line_total=clean_str("items.total").cast(pl.Float64, strict=False).round(2),
    )
